using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using UnityEngine.Rendering.Universal;

namespace Snowglow.Editor {
 // A saved, repeat-safe content arrangement. Nothing here runs in a player.
 public static class IsometricLayoutAuthoring {
  public const string Marker="Presentation | isometric-facing layout v1";
  const string Request="Logs/IsometricLayout.request",Logs="Logs/IsometricLayout",ReaderName="Authoring | road reading position",RearName="Presentation | rear sign artwork";
  static readonly Vector3 Viewer=-(Quaternion.Euler(41,45,0)*Vector3.forward);
  static int checks;
  static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
  static bool Sign(CatalogPlacement p)=>(p.assetId??"").StartsWith("alpine-sign-",StringComparison.Ordinal);
  static bool Home(CatalogPlacement p)=>(p.placementId??"").StartsWith("pinefall-home-",StringComparison.Ordinal);
  static Vector3 Flat(Vector3 v)=>new Vector3(v.x,0,v.z);
  static void Check(bool ok,string message){checks++;if(!ok)throw new InvalidOperationException("Isometric layout: "+message);}
  public static bool Applied(Scene s)=>All<Transform>(s).Any(t=>t.name==Marker);
  public static bool TryReader(Scene s,string id,out Vector3 reader){var p=All<CatalogPlacement>(s).SingleOrDefault(x=>x.placementId==id);var t=p?p.transform.Find(ReaderName):null;reader=t?t.position:Vector3.zero;return t;}
  [InitializeOnLoadMethod]static void Register(){EditorApplication.update+=Pending;}
  static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;string mode=File.ReadAllText(Request).Trim();File.Delete(Request);try{Apply(mode=="two-sided");}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  [MenuItem("Snowglow/Environment/Arrange detailed faces for isometric")]
  public static void Menu()=>Apply(true);
  static Bounds BoundsOf(GameObject go){var rs=go.GetComponentsInChildren<Renderer>(true).Where(r=>!(r is ParticleSystemRenderer)).ToArray();Check(rs.Length>0,"no renderers "+go.name);var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}
  static bool Overlap(Bounds a,Bounds b,float gap)=>a.min.x<b.max.x+gap&&a.max.x>b.min.x-gap&&a.min.z<b.max.z+gap&&a.max.z>b.min.z-gap;
  static Transform Face(CatalogPlacement p)=>p.GetComponentsInChildren<AssetAnchor>(true).Single(a=>a.id=="label-face").transform;
  static string SnowValues(SnowSeed seed)=>JsonUtility.ToJson(new SnowVolumeGrid{depth=seed.grid.depth,credit=seed.grid.credit,initialVolume=seed.grid.initialVolume,disposed=seed.grid.disposed,revision=seed.grid.revision,blocked=new bool[0]});
  static void Move(Transform t,Vector3 position,Quaternion rotation){Undo.RecordObject(t,"Arrange isometric-facing scenery");t.SetPositionAndRotation(position,rotation);if(PrefabUtility.IsPartOfPrefabInstance(t))PrefabUtility.RecordPrefabInstancePropertyModifications(t);}
  static void Aim(CatalogPlacement p,Vector3 position,Vector3 outward,Terrain terrain){var local=p.transform.InverseTransformDirection(-Face(p).forward);position.y=terrain.SampleHeight(position)+terrain.transform.position.y-.015f;Move(p.transform,position,Quaternion.LookRotation(outward.normalized,Vector3.up)*Quaternion.Inverse(Quaternion.LookRotation(local,Vector3.up)));}
  static bool ClearReading(CatalogPlacement p,Vector3 eye){var end=Face(p).position+Vector3.up*.2f;var ray=end-eye;return !Physics.RaycastAll(eye,ray.normalized,ray.magnitude-.03f,~0,QueryTriggerInteraction.Ignore).Any(h=>!h.collider.GetComponentInParent<SnowField>()&&!h.collider.GetComponentInParent<MachineController>()&&h.collider.GetComponentInParent<CatalogPlacement>()!=p);}
  static Vector3 FindReader(CatalogPlacement p,Terrain terrain,Bounds[] roads){
   var front=Flat(-Face(p).forward).normalized;
   if(p.placementId.Contains("boundary")||p.placementId=="pinefall-sign-08"){var v=Flat(p.transform.position)-Flat(p.transform.position).normalized*10;v.y=terrain.SampleHeight(v)+terrain.transform.position.y+1.8f;return v;}
   foreach(float angle in new[]{0f,-10,10,-20,20,-30,30})for(float distance=7;distance<=16;distance+=.5f){var at=p.transform.position+Quaternion.Euler(0,angle,0)*front*distance;if(!roads.Any(b=>at.x>b.min.x+.1f&&at.x<b.max.x-.1f&&at.z>b.min.z+.1f&&at.z<b.max.z-.1f))continue;at.y=terrain.SampleHeight(at)+terrain.transform.position.y+1.8f;if(ClearReading(p,at))return at;}
   throw new InvalidOperationException("No clear road reader for "+p.placementId);
  }
  static void SaveReader(CatalogPlacement p,Vector3 position){var t=p.transform.Find(ReaderName);if(!t){var go=new GameObject(ReaderName);Undo.RegisterCreatedObjectUndo(go,"Save sign reading position");go.transform.SetParent(p.transform,false);t=go.transform;}Move(t,position,Quaternion.identity);}
  static int Mask(SnowField snow){Physics.SyncTransforms();var mask=(bool[])snow.seed.grid.blocked.Clone();int changed=0;for(int i=0;i<mask.Length;i++){bool value=Physics.CheckBox(new Vector3(snow.seed.grid.X(i),SnowField.Ground+.85f,snow.seed.grid.Z(i)),new Vector3(SnowVolumeGrid.Cell*.45f,.65f,SnowVolumeGrid.Cell*.45f),Quaternion.identity,1<<0,QueryTriggerInteraction.Ignore);if(value!=mask[i]){mask[i]=value;changed++;}}if(changed>0){var copy=UnityEngine.Object.Instantiate(snow.seed);copy.name="Pinefall | isometric arrangement obstacles";copy.grid.blocked=mask;AssetDatabase.CreateAsset(copy,AssetDatabase.GenerateUniqueAssetPath(CatalogPreparation.Root+"/SceneData/IsometricLayoutSnowObstacles.asset"));Undo.RecordObject(snow,"Bind updated scenery obstacles");snow.seed=copy;EditorUtility.SetDirty(snow);}return changed;}
  static void Corridor(Vector3[] path,string name){for(int i=1;i<path.Length;i++){var from=path[i-1]+Vector3.up*(SnowField.Ground+2.7f);var to=path[i]+Vector3.up*(SnowField.Ground+2.7f);var d=to-from;var hits=Physics.SphereCastAll(from,2.2f,d.normalized,d.magnitude,1<<0,QueryTriggerInteraction.Ignore).Where(h=>!h.collider.GetComponentInParent<SnowField>()).ToArray();Check(hits.Length==0,name+" blocked by "+string.Join(", ",hits.Select(h=>h.collider.name)));}}
  static void RearArtwork(CatalogPlacement p){
   var old=p.transform.Find(RearName);if(old&&old.Find("Prepared panel and artwork"))return;
   string index=p.assetId.Substring(p.assetId.Length-2);Check(index=="04"||index=="05","rear panel source not prepared "+p.assetId);
   string path=CatalogPreparation.Root+"/Sources/AlpineSignBoards/RearPanel"+index+".fbx";
   var palette=AssetDatabase.LoadAssetAtPath<Material>(CatalogPreparation.Root+"/Sources/AlpineSignBoards/SignPalette.mat");
   var importer=AssetImporter.GetAtPath(path) as ModelImporter;Check(importer!=null,"rear panel FBX not imported");
   importer.importCameras=false;importer.importLights=false;importer.importAnimation=false;importer.globalScale=1;importer.isReadable=false;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"SignPalette"),palette);importer.SaveAndReimport();
   var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);Check(model&&palette,"rear panel bindings missing");
   if(old)Undo.DestroyObjectImmediate(old.gameObject);var group=new GameObject(RearName);group.transform.SetParent(p.transform,false);Undo.RegisterCreatedObjectUndo(group,"Author supported rear sign face");
   var copy=(GameObject)PrefabUtility.InstantiatePrefab(model,p.gameObject.scene);copy.name="Prepared panel and artwork";copy.transform.SetParent(group.transform,false);copy.transform.localPosition=Vector3.zero;
   foreach(var r in copy.GetComponentsInChildren<MeshRenderer>(true)){r.sharedMaterial=palette;r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;r.receiveShadows=true;}
   Check(copy.GetComponentsInChildren<Collider>(true).Length==0&&copy.GetComponentsInChildren<Light>(true).Length==0,"rear panel introduced collision/light");
   var b=BoundsOf(copy);Check(b.min.y>p.transform.position.y+.9f&&b.max.y<p.transform.position.y+3.05f,"rear panel height/scale");Check(Vector3.Dot(b.center-p.transform.position,-Face(p).forward)<-.1f,"rear panel not behind board");Check(Mathf.Abs(Vector3.Dot(b.center-p.transform.position,Face(p).right))<.2f,"rear panel horizontal alignment");
  }
  static void RearPreviews(Scene s){
   foreach(string id in new[]{"pinefall-sign-09","pinefall-sign-boundary-08"}){var sign=All<CatalogPlacement>(s).Single(p=>p.placementId==id);var preview=new PreviewRenderUtility();try{var copy=UnityEngine.Object.Instantiate(sign.gameObject);copy.transform.position=Vector3.zero;preview.AddSingleGO(copy);var b=BoundsOf(copy);var normal=-Face(copy.GetComponent<CatalogPlacement>()).forward;preview.camera.orthographic=true;preview.camera.orthographicSize=b.extents.y*1.2f;preview.camera.aspect=4f/3;preview.camera.nearClipPlane=.03f;preview.camera.farClipPlane=100;preview.camera.clearFlags=CameraClearFlags.SolidColor;preview.camera.backgroundColor=new Color(.22f,.32f,.4f);preview.ambientColor=new Color(.5f,.5f,.5f);preview.lights[0].intensity=1.2f;
    foreach(int side in new[]{1,-1}){preview.camera.transform.position=b.center+normal*side*15;preview.camera.transform.LookAt(b.center);preview.lights[0].transform.rotation=preview.camera.transform.rotation;preview.BeginStaticPreview(new Rect(0,0,960,720));preview.Render(true);var image=preview.EndStaticPreview();File.WriteAllBytes(Logs+"/RearPanel-"+id+(side==1?"-front.png":"-back.png"),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}
   }finally{preview.Cleanup();}}
  }
  public static void ValidateSigns(Scene s){
   var signs=All<CatalogPlacement>(s).Where(Sign).ToArray();Check(signs.Length==30,"preserve saved thirty-board layout");var roads=All<Renderer>(s).Where(r=>r.name=="Road | asphalt").Select(r=>r.bounds).ToArray();var terrain=All<Terrain>(s).Single();
   foreach(var p in signs){Check(TryReader(s,p.placementId,out var eye),"missing saved reader "+p.placementId);var f=Flat(-Face(p).forward).normalized;Check(Vector3.Dot(f,Flat(eye-p.transform.position).normalized)>.80f,"reader behind primary face "+p.placementId);Check(ClearReading(p,eye),"blocked reader "+p.placementId);Check(!roads.Any(b=>Overlap(BoundsOf(p.gameObject),b,.25f)),"sign intrudes on road "+p.placementId);Check(Mathf.Abs(p.transform.position.y-(terrain.SampleHeight(p.transform.position)+terrain.transform.position.y-.015f))<.025f,"unseated sign "+p.placementId);}
   foreach(var id in new[]{"pinefall-sign-07","pinefall-sign-12"}){var p=signs.Single(x=>x.placementId==id);var target=id=="pinefall-sign-07"?FacilityAccessAuthoring.DepotEntry(s):Vector3.zero;Check(Vector3.Dot(Flat(Face(p).right).normalized,Flat(target-p.transform.position).normalized)>.75f,"physical arrow points away "+id);}
  }
  public static void ValidateLayout(Scene s){
   var ps=All<CatalogPlacement>(s);var homes=ps.Where(Home).ToArray();Check(homes.Length==40,"house count");var through=All<Renderer>(s).Where(r=>r.name=="Road | asphalt"&&(r.bounds.size.x>150||r.bounds.size.z>150)).Select(r=>r.bounds).ToArray();var roadBounds=All<Renderer>(s).Where(r=>r.name=="Road | asphalt").Select(r=>r.bounds).ToArray();
   for(int i=0;i<homes.Length;i++){var b=BoundsOf(homes[i].gameObject);Check(!roadBounds.Any(r=>Overlap(b,r,.25f)),"house over road "+homes[i].placementId);for(int j=0;j<i;j++)Check(!Overlap(b,BoundsOf(homes[j].gameObject),.25f),"house overlap "+homes[i].placementId+" / "+homes[j].placementId);Check(Vector3.Dot(homes[i].transform.forward,Viewer)>.5f,"house entrance faces away "+homes[i].placementId);Check(Vector3.Dot(-homes[i].transform.right,Viewer)>.5f,"detailed house side faces away "+homes[i].placementId);}
   var garage=ps.Single(p=>p.placementId=="pinefall-garage");var yard=ps.Single(p=>p.placementId=="pinefall-disposal-yard");foreach(var p in new[]{garage,yard}){if(!FacilityAccessAuthoring.Applied(s))Check(Vector3.Dot(p.transform.forward,Viewer)>.5f,"facility front faces away "+p.placementId);Check(!through.Any(r=>Overlap(BoundsOf(p.gameObject),r,.25f)),"facility over through-road "+p.placementId);}
   foreach(var machine in All<MachineController>(s))foreach(var box in machine.GetComponentsInChildren<BoxCollider>(true))foreach(var wall in garage.GetComponentsInChildren<MeshCollider>(true))Check(!Physics.ComputePenetration(box,box.transform.position,box.transform.rotation,wall,wall.transform.position,wall.transform.rotation,out _,out _),"garage intersects parked machine "+machine.name);
   var pad=yard.GetComponentsInChildren<Renderer>().Single(r=>r.name.StartsWith("01 Ground pad",StringComparison.Ordinal)).bounds;foreach(float x in new[]{79f,109})foreach(float z in new[]{-98f,-71})Check(x>pad.min.x&&x<pad.max.x&&z>pad.min.z&&z<pad.max.z,"yard moved off accounting rectangle");
   if(FacilityAccessAuthoring.Applied(s))FacilityAccessAuthoring.ValidateRoutes(s);
   else{Corridor(new[]{new Vector3(-65,0,-90),new Vector3(-65,0,-115.5f),new Vector3(-94,0,-115.5f),new Vector3(-94,0,-112)},"garage approach");
   Corridor(new[]{new Vector3(65,0,-106),new Vector3(94,0,-106),new Vector3(94,0,-96)},"yard approach");}ValidateSigns(s);
  }
  static void Render(Camera c,string file){var rt=new RenderTexture(1280,720,24);var old=c.targetTexture;var active=RenderTexture.active;Texture2D image=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(Logs+"/"+file+".png",image.EncodeToPNG());}finally{c.targetTexture=old;RenderTexture.active=active;rt.Release();UnityEngine.Object.DestroyImmediate(rt);if(image)UnityEngine.Object.DestroyImmediate(image);}}
  static void Views(Scene s,string phase){var ps=All<CatalogPlacement>(s);var source=All<CameraRig>(s).Single();var go=new GameObject("Temporary layout review camera"){hideFlags=HideFlags.HideAndDontSave};var target=new GameObject("Temporary layout subject"){hideFlags=HideFlags.HideAndDontSave};try{var c=go.AddComponent<Camera>();c.CopyFrom(source.view);c.enabled=false;c.aspect=16f/9;go.AddComponent<UniversalAdditionalCameraData>().renderPostProcessing=false;var rig=go.AddComponent<CameraRig>();rig.view=c;rig.terrain=source.terrain;rig.SetMode(CameraMode.Isometric);foreach(var id in new[]{"pinefall-garage","pinefall-disposal-yard","pinefall-home-01","pinefall-home-04","pinefall-home-05","pinefall-home-06","pinefall-home-10","pinefall-home-20","pinefall-home-30","pinefall-sign-05","pinefall-sign-06","pinefall-sign-07","pinefall-sign-12","pinefall-sign-09","pinefall-sign-boundary-08"}){var p=ps.Single(x=>x.placementId==id);target.transform.position=p.transform.position;rig.ResetView();for(int n=0;n<120;n++)rig.UpdateForTarget(target.transform,1f/60,true,0);Render(c,phase+"-"+id);}
   foreach(var mode in new[]{CameraMode.Follow,CameraMode.Orbit}){rig.SetMode(mode);target.transform.SetPositionAndRotation(new Vector3(-94,SnowField.Ground,-112),Quaternion.identity);rig.ResetView();for(int n=0;n<120;n++)rig.UpdateForTarget(target.transform,1f/60,true,0);Render(c,phase+"-garage-"+mode);}
   }finally{UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(target);}}
  static string Pose(Transform t)=>t.localToWorldMatrix.ToString("R");
  public static void Apply(bool rearArtwork){
   Check(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");var s=SceneManager.GetActiveScene();Check(s.path==SceneValidation.ScenePath,"open Pinefall");Directory.CreateDirectory(Logs);checks=0;SceneValidation.Validate(s);
   if(Applied(s)){
    var snowBefore=All<SnowField>(s).Single();string valuesBefore=SnowValues(snowBefore.seed),seedPath=AssetDatabase.GetAssetPath(snowBefore.seed);var seedHash=AssetDatabase.GetAssetDependencyHash(seedPath);var poses=All<CatalogPlacement>(s).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>p.placementId,p=>Pose(p.transform));
    Check(EditorSceneManager.SaveScene(s,Logs+"/Pinefall-before-rear-panels.unity",true),"rear panel backup");Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();bool written=false;
    try{if(rearArtwork)foreach(var p in All<CatalogPlacement>(s).Where(Sign).Where(p=>p.transform.Find(RearName)))RearArtwork(p);Physics.SyncTransforms();ValidateLayout(s);SceneValidation.Validate(s);MechanicsChecks.Run();Check(valuesBefore==SnowValues(snowBefore.seed)&&seedHash==AssetDatabase.GetAssetDependencyHash(seedPath),"rear panels changed snow");foreach(var p in All<CatalogPlacement>(s).Where(p=>!string.IsNullOrEmpty(p.placementId)))Check(poses[p.placementId]==Pose(p.transform),"rear repair moved "+p.placementId);Views(s,"After");RearPreviews(s);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);Check(EditorSceneManager.SaveScene(s),"rear panel save");written=true;Undo.CollapseUndoOperations(group);s=EditorSceneManager.OpenScene(SceneValidation.ScenePath);ValidateLayout(s);SceneValidation.Validate(s);MechanicsChecks.Run();Check(seedHash==AssetDatabase.GetAssetDependencyHash(seedPath),"reopened snow seed changed");int triangles=All<CatalogPlacement>(s).Where(Sign).Select(p=>p.transform.Find(RearName)).Where(t=>t).SelectMany(t=>t.GetComponentsInChildren<MeshFilter>(true)).Sum(m=>Enumerable.Range(0,m.sharedMesh.subMeshCount).Sum(i=>(int)m.sharedMesh.GetIndexCount(i)/3));File.AppendAllText(Logs+"/Validation.txt","\nPASS: supported rear-panel repair; "+checks+" assertions, save/reopen, scene/19 snow checks. Twelve shared-model rear panels, "+triangles+" triangles total, existing opaque palette; no posts duplicated, collisions/lights added or placement/snow changes. Four front/back close-ups and refreshed After views written; 4.4 m-wide approach sweeps clear. Native render inspection and device limits reported separately.\n");
    }catch{if(!written)Undo.RevertAllDownToGroup(group);throw;}return;
   }
   string stamp=DateTime.Now.ToString("yyyyMMdd_HHmmss");Check(EditorSceneManager.SaveScene(s,Logs+"/Pinefall-before-"+stamp+".unity",true),"backup failed");var ps=All<CatalogPlacement>(s).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToArray();var session=All<PrototypeSession>(s).Single();var snow=session.Snow;string values=SnowValues(snow.seed);var originalSeed=snow.seed;var protectedPaths=All<Terrain>(s).Select(t=>AssetDatabase.GetAssetPath(t.terrainData)).Concat(snow.GetComponentsInChildren<MeshFilter>(true).Select(m=>AssetDatabase.GetAssetPath(m.sharedMesh))).Concat(new[]{AssetDatabase.GetAssetPath(originalSeed)}).Where(x=>!string.IsNullOrEmpty(x)).Distinct().ToDictionary(x=>x,x=>AssetDatabase.GetAssetDependencyHash(x));var protectedPoses=ps.Where(p=>!Home(p)&&!Sign(p)&&p.placementId!="pinefall-garage"&&p.placementId!="pinefall-disposal-yard").ToDictionary(p=>p.placementId,p=>Pose(p.transform));var fleet= session.Fleet.Select(m=>Pose(m.transform)).ToArray();var ids=ps.ToDictionary(p=>p.placementId,p=>p.assetId);var terrain=All<Terrain>(s).Single();var roads=All<Renderer>(s).Where(r=>r.name=="Road | asphalt").Select(r=>r.bounds).ToArray();Views(s,"Before");Undo.IncrementCurrentGroup();int undo=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("Arrange detailed scenery faces for isometric");bool saved=false;
   try{
    foreach(var p in ps.Where(Home)){var lot=p.transform.parent;Check(lot&&lot.name.StartsWith("Home lot",StringComparison.Ordinal),"house lot missing "+p.placementId);Move(lot,lot.position,Quaternion.AngleAxis(90,Vector3.up)*lot.rotation);}
    var garage=ps.Single(p=>p.placementId=="pinefall-garage");Move(garage.transform,new Vector3(-94,garage.transform.position.y,-103),Quaternion.Euler(0,180,0));var yard=ps.Single(p=>p.placementId=="pinefall-disposal-yard");Move(yard.transform,yard.transform.position,Quaternion.Euler(0,180,0));
    Aim(ps.Single(p=>p.placementId=="pinefall-sign-05"),ps.Single(p=>p.placementId=="pinefall-sign-05").transform.position,new Vector3(-1,0,-1),terrain);
    var lodge=ps.Single(p=>p.placementId=="pinefall-sign-06");Aim(lodge,lodge.transform.position,new Vector3(-1,0,-1),terrain);
    Aim(ps.Single(p=>p.placementId=="pinefall-sign-07"),new Vector3(-72.5f,0,-73),new Vector3(-Mathf.Cos(15*Mathf.Deg2Rad),0,Mathf.Sin(15*Mathf.Deg2Rad)),terrain);
    Aim(ps.Single(p=>p.placementId=="pinefall-sign-12"),new Vector3(7.5f,0,12),Vector3.left,terrain);Physics.SyncTransforms();
    foreach(var p in ps.Where(Sign))SaveReader(p,FindReader(p,terrain,roads));
    var entry=ps.Single(p=>p.placementId=="pinefall-home-40").GetComponentsInChildren<AssetAnchor>(true).Single(a=>a.role==AnchorRole.Entrance).transform.position;Check(TryReader(s,lodge.placementId,out var lodgeReader),"lodge reader");var arrow=Vector3.Dot(Flat(Face(lodge).right).normalized,Flat(entry-lodge.transform.position).normalized);Check(Mathf.Abs(arrow)>.75f,"lodge arrow target");foreach(var caption in lodge.GetComponentsInChildren<TextMesh>(true))if(caption.text.TrimStart().StartsWith(">",StringComparison.Ordinal)||caption.text.TrimStart().StartsWith("<",StringComparison.Ordinal)){Undo.RecordObject(caption,"Update lodge approach arrow");caption.text=(arrow>0?"> ":"< ")+(Mathf.RoundToInt(Flat(entry-lodgeReader).magnitude/5)*5)+" m";EditorUtility.SetDirty(caption);}
    int rear=0;if(rearArtwork)foreach(var p in ps.Where(Sign)){if(Vector3.Dot(-Face(p).forward,Viewer)<.05f){RearArtwork(p);rear++;}}
    SignLabelDepthAuthoring.Apply(s);var marker=new GameObject(Marker);Undo.RegisterCreatedObjectUndo(marker,"Mark saved presentation layout");SceneManager.MoveGameObjectToScene(marker,s);Physics.SyncTransforms();ValidateLayout(s);int mask=Mask(snow);Check(SnowValues(snow.seed)==values,"snow values changed");foreach(var h in protectedPaths)Check(h.Value==AssetDatabase.GetAssetDependencyHash(h.Key),"protected snow/Terrain asset changed "+h.Key);foreach(var p in ps.Where(p=>protectedPoses.ContainsKey(p.placementId)))Check(Pose(p.transform)==protectedPoses[p.placementId],"unrelated placement changed "+p.placementId);Check(fleet.SequenceEqual(session.Fleet.Select(m=>Pose(m.transform))),"fleet poses changed");SceneValidation.Validate(s);MechanicsChecks.Run();Views(s,"After");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);Check(EditorSceneManager.SaveScene(s),"scene save failed");saved=true;Undo.CollapseUndoOperations(undo);
    s=EditorSceneManager.OpenScene(SceneValidation.ScenePath);ValidateLayout(s);SceneValidation.Validate(s);MechanicsChecks.Run();Check(values==SnowValues(All<SnowField>(s).Single().seed),"reopened snow values changed");foreach(var p in All<CatalogPlacement>(s).Where(p=>!string.IsNullOrEmpty(p.placementId)))Check(ids.TryGetValue(p.placementId,out var id)&&id==p.assetId,"catalog identity changed "+p.placementId);Check(All<CatalogPlacement>(s).Count(p=>!string.IsNullOrEmpty(p.placementId))==ids.Count,"placement count changed");
    var report=new StringBuilder("PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+". "+checks+" assertions. Scene saved/reopened; scene validation and 19 snow checks passed.\n");report.AppendLine("40 home lots rotated together by +90 degrees, including their foundations and rear fences: entrance west, detailed side south. Garage moved to (-94, 5.13, -103), facade south; yard rotated south with pad/accounting footprint retained. Directory/lodge face southwest; depot/Town Center signs relocated and aimed with physical arrows checked. Existing thirty signs retained; removed Workshop board not recreated. Rear artwork groups added: "+rear+". Updated obstacle cells: "+mask+" in separate seed copy; original seed/meshes, depth, credit, volume, revision and terrain preserved. Fuel station, all other catalog poses, fleet poses/IDs and player saves untouched. Garage/yard 2.8 m-wide sampled approach corridors clear; these are geometric queries, not driving tests. No new real-time lights or runtime assembly. Downward fixtures remain underside details; no placement can make all such surfaces visible from above. Native before/after isometric and depot Follow/Orbit views written. Phone performance, full live routes, touch readability and Android packaging untested.");File.WriteAllText(Logs+"/Validation.txt",report.ToString());Debug.Log(report.ToString());
   }catch{if(!saved)Undo.RevertAllDownToGroup(undo);throw;}
  }
 }
